{
  "title": "High error rate on account-service",
  "description": "5xx spike observed in the last 10 minutes. Transfers are failing intermittently.",
  "service": "account-service",
  "category": "errors",
  "severity": "WARNING",
  "context": {
    "triggeredBy": "postman-test",
    "endpoint": "/api/accounts/{id}/debit"
  }
}

{
  "message": "Why is transaction-service returning errors and what should I do?"
}

{
  "message": "Check the Loki logs for the last 30 minutes and tell me what errors you see.",
  "incidentId": "{{incidentId}}"
}

{
  "version": "4",
  "status": "firing",
  "alerts": [
    {
      "status": "firing",
      "fingerprint": "sim-service-down-1",
      "labels": {
        "alertname": "ServiceDown",
        "severity": "critical",
        "category": "availability",
        "application": "account-service",
        "job": "account-service"
      },
      "annotations": {
        "summary": "account-service is down",
        "description": "Prometheus target account-service:8081 has been unreachable for more than 30s."
      }
    }
  ]
}

{
  "version": "4",
  "status": "firing",
  "alerts": [
    {
      "status": "firing",
      "fingerprint": "sim-high-error-rate-1",
      "labels": {
        "alertname": "HighErrorRate",
        "severity": "warning",
        "category": "errors",
        "application": "transaction-service",
        "job": "transaction-service"
      },
      "annotations": {
        "summary": "Elevated 5xx rate on transaction-service",
        "description": "More than 5% of requests are failing with 5xx on transaction-service over the last 2 minutes."
      }
    }
  ]
}

{
  "version": "4",
  "status": "firing",
  "alerts": [
    {
      "status": "firing",
      "fingerprint": "sim-high-latency-1",
      "labels": {
        "alertname": "HighLatencyP95",
        "severity": "warning",
        "category": "latency",
        "application": "payment-service",
        "job": "payment-service"
      },
      "annotations": {
        "summary": "High p95 latency on payment-service",
        "description": "p95 request latency exceeds 2s on payment-service over the last 5 minutes. Inspect slow spans in Tempo."
      }
    }
  ]
}

{
  "version": "4",
  "status": "firing",
  "alerts": [
    {
      "status": "firing",
      "fingerprint": "sim-cb-open-1",
      "labels": {
        "alertname": "CircuitBreakerOpen",
        "severity": "critical",
        "category": "resiliency",
        "application": "transaction-service",
        "job": "transaction-service"
      },
      "annotations": {
        "summary": "Circuit breaker open on transaction-service",
        "description": "Circuit breaker account-service-cb is OPEN — downstream calls are failing fast. Check health and mitigation playbooks."
      }
    }
  ]
}

{
  "version": "4",
  "status": "firing",
  "alerts": [
    {
      "status": "firing",
      "fingerprint": "sim-db-unhealthy-1",
      "labels": {
        "alertname": "DatabaseUnhealthy",
        "severity": "critical",
        "category": "database",
        "application": "account-service",
        "job": "account-service"
      },
      "annotations": {
        "summary": "Health check DOWN on account-service",
        "description": "Spring Boot health reports DOWN — likely DB or downstream dependency. Inspect /actuator/health and Postgres connectivity."
      }
    }
  ]
}
